package com.markethub.catalog.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="products",indexes={@Index(name="ix_products_vendor_status",columnList="vendor_id,status"),@Index(name="ix_products_slug",columnList="slug",unique=true)})
public class Product { @Id private UUID id; @Column(name="vendor_id",nullable=false) private UUID vendorId; @Column(nullable=false,length=180) private String name; @Column(nullable=false,length=200,unique=true) private String slug; @Column(nullable=false,precision=19,scale=4) private BigDecimal price; @Column(nullable=false,length=20) private String currency; @Column(nullable=false,length=20) private String status; @Version private long version; @Column(nullable=false) private Instant createdAt; protected Product(){} public UUID getId(){return id;} public UUID getVendorId(){return vendorId;} public String getName(){return name;} public String getSlug(){return slug;} public BigDecimal getPrice(){return price;} public String getCurrency(){return currency;} public String getStatus(){return status;} public long getVersion(){return version;} public Instant getCreatedAt(){return createdAt;} }